public enum SeatStatus { Available, Locked, Booked }

public class Seat
{
    public string Row { get; }
    public int Number { get; }
    public SeatStatus Status { get; internal set; } = SeatStatus.Available;
    public decimal Price { get; set; }
}

public class Show
{
    public Guid Id { get; } = Guid.NewGuid();
    public string MovieTitle { get; }
    public DateTime StartTime { get; }
    public int ScreenNumber { get; }
    private readonly Dictionary<(string row, int num), Seat> _seats;

    public Show(string movieTitle, DateTime startTime, int screenNumber,
                IEnumerable<(string row, int num, decimal price)> seatDefs)
    {
        MovieTitle = movieTitle;
        StartTime = startTime;
        ScreenNumber = screenNumber;
        _seats = seatDefs.ToDictionary(
            s => (s.row, s.num),
            s => new Seat { Row = s.row, Number = s.num, Price = s.price });
    }

    public IReadOnlyCollection<Seat> GetAvailableSeats() =>
        _seats.Values.Where(s => s.Status == SeatStatus.Available).ToList();

    public bool TryLockSeat(string row, int num)
    {
        var key = (row, num);
        if (!_seats.TryGetValue(key, out var seat) || seat.Status != SeatStatus.Available)
            return false;
        seat.Status = SeatStatus.Locked;
        return true;
    }

    public void ConfirmBooking(string row, int num)
    {
        _seats[(row, num)].Status = SeatStatus.Booked;
    }
}

public class Booking
{
    public string Id { get; } = Guid.NewGuid().ToString();
    public Show Show { get; }
    public string UserEmail { get; }
    public IReadOnlyCollection<Seat> Seats { get; }
    public decimal Total => Seats.Sum(s => s.Price);
    public DateTime BookedAt { get; } = DateTime.UtcNow;
}
